}
_DATA_MARKER = "<!-- REPORT_DATA -->"
_REFERENCE_IDENTITIES = ("nutri", "adriana hoyos", "artz", "shamuna")
_ASSET_HOSTS = frozenset()


def _json_value(value: Any) -> Any:
