    user_id: str = "",
    api_key: str = "",
) -> dict[str, Any]:
    """Normalize dashboard state without leaking credentials into the report."""
    del template_name
    query_context = query_context or {}
    current_rows = _records(current)
    previous_rows = _records(previous)
    export_rows = _records(export_table)
    metrics = sorted(set(_metric_names(current_rows, previous_rows, export_rows)) | set(query_context.get("required_metrics", [])))
    supplemental_rows = _fetch_supplemental(
        metrics,
        current_rows,
        export_rows,
        query_context,
        client_id,
        user_id,
